  _G.TalentedTooltipData = _G.TalentedTooltipData or {}
  local tooltipData = _G.TalentedTooltipData
  _G.TalentedDataOverride = _G.TalentedDataOverride or {spelldata = {}, tabdata = {}}
  local overrideRoot = _G.TalentedDataOverride
  overrideRoot.spelldata = overrideRoot.spelldata or {}

  for class, tabs in pairs(payload) do
    tooltipData[class] = {}
    overrideRoot.spelldata[class] = {}
    for tab = 1, table.getn(tabs) do
      local srcTalents = tabs[tab]
      local compact = {}
      for i = 1, table.getn(srcTalents) do
        local src = srcTalents[i]
        local entry = {
          name = src.name,
          row = src.row,
          column = src.column,
          icon = src.icon,
          desc = src.desc,
          ranks = src.ranks,
        }
        if src.req then entry.req = src.req end
        compact[i] = entry
      end
      tooltipData[class][tab] = compact
      overrideRoot.spelldata[class][tab] = compact
    end
  end
